const maxN = Number(process.argv[2] ?? 20);

function tailsAndCycles(n) {
  const N = 1 << n;
  const mask = N - 1;
  const f = new Int32Array(N);
  for (let r = 0; r < N; r++) f[r] = ((4 * r) ^ ((2 * r) | r)) & mask;

